+  return ret;
+}
+
+static time_t
+get_time(int time)
+{
+  struct tm tm;
+  tm.tm_sec = 2 * (time & 0x1f);
+  tm.tm_min = (time >> 5) & 0x3f;
+  tm.tm_hour = (time >> 11) & 0x1f;
+  tm.tm_mday = (time >> 16) & 0x1f;
+  tm.tm_mon = ((time >> 21) & 0x0f) - 1;
+  tm.tm_year = ((time >> 25) & 0x7f) + 80;
+  tm.tm_isdst = -1;
+  return mktime(&tm);
+}
+
+static void
+read_exttime(struct archive_entry *entry, const char *p, struct rar *rar)
+{
+  unsigned rmode, flags, rem, count;
+  int time, i, j;
+  struct tm *tm;
+  time_t t;
+  long nsec;
+
+  flags = archive_le16dec(p);
+  p += 2;
+
+  for (i = 3; i >= 0; i--)
+  {
+    t = 0;
+    if (i == 3)
+      t = rar->mtime;
+    rmode = flags >> i * 4;
+    if (rmode & 8)
+    {
+      if (!t)
+      {
+        time = archive_le32dec(p);
+        t = get_time(time);
+        p += 4;
+      }
+      rem = 0;
+      count = rmode & 3;
+      for (j = 0; j < count; j++)
+      {
+        rem = ((*p) << 16) | (rem >> 8);
+        p++;
+      }
+      tm = localtime(&t);
+      nsec = tm->tm_sec + rem / NS_UNIT;
+      if (rmode & 4)
+      {
+        tm->tm_sec++;
+        t = mktime(tm);
+      }
+      if (i == 3)
+      {
+        rar->mtime = t;
+        rar->mnsec = nsec;
+      }
+      else if (i == 2)
+      {
+        rar->ctime = t;
+        rar->cnsec = nsec;
+      }
+      else if (i == 1)
+      {
+        rar->atime = t;
+        rar->ansec = nsec;
+      }
+      else
+      {
+        rar->arctime = t;
+        rar->arcnsec = nsec;
+      }
+    }
+  }
+}
