  case simdjson::dom::element_type::OBJECT:
    os << "{";
    {
      simdjson::dom::object object = element.get_object().value_unsafe();
      for (simdjson::dom::key_value_pair field : object) {
        os << "\"" << field.key << "\": ";
        print_json(os, field.value);
      }
