+++ b/libevmasm/SemanticInformation.cpp
@@ -551,34 +551,35 @@ SemanticInformation::Effect SemanticInformation::otherState(Instruction _instruc
 bool SemanticInformation::invalidInPureFunctions(Instruction _instruction)
 {
 	switch (_instruction)
 	{
 	case Instruction::ADDRESS:
 	case Instruction::SELFBALANCE:
 	case Instruction::BALANCE:
 	case Instruction::ORIGIN:
 	case Instruction::CALLER:
 	case Instruction::CALLVALUE:
 	case Instruction::CHAINID:
 	case Instruction::BASEFEE:
 	case Instruction::BLOBBASEFEE:
+	case Instruction::SLOTNUM:
 	case Instruction::GAS:
 	case Instruction::GASPRICE:
 	case Instruction::EXTCODESIZE:
 	case Instruction::EXTCODECOPY:
 	case Instruction::EXTCODEHASH:
 	case Instruction::BLOCKHASH:
 	case Instruction::BLOBHASH:
 	case Instruction::COINBASE:
 	case Instruction::TIMESTAMP:
 	case Instruction::NUMBER:
 	case Instruction::PREVRANDAO:
 	case Instruction::GASLIMIT:
 	case Instruction::STATICCALL:
 	case Instruction::SLOAD:
 	case Instruction::TLOAD:
 		return true;
 	default:
 		break;
 	}
 	return invalidInViewFunctions(_instruction);
 }
