--- a/liblangutil/EVMVersion.cpp
+++ b/liblangutil/EVMVersion.cpp
@@ -29,38 +29,40 @@ using namespace solidity::langutil;
 bool EVMVersion::hasOpcode(Instruction _opcode) const
 {
 	switch (_opcode)
 	{
 	case Instruction::RETURNDATACOPY:
 	case Instruction::RETURNDATASIZE:
 		return supportsReturndata();
 	case Instruction::STATICCALL:
 		return hasStaticCall();
 	case Instruction::SHL:
 	case Instruction::SHR:
 	case Instruction::SAR:
 		return hasBitwiseShifting();
 	case Instruction::CLZ:
 		return hasCLZ();
 	case Instruction::CREATE2:
 		return hasCreate2();
 	case Instruction::EXTCODEHASH:
 		return hasExtCodeHash();
 	case Instruction::CHAINID:
 		return hasChainID();
 	case Instruction::SELFBALANCE:
 		return hasSelfBalance();
 	case Instruction::BASEFEE:
 		return hasBaseFee();
 	case Instruction::BLOBHASH:
 		return hasBlobHash();
 	case Instruction::BLOBBASEFEE:
 		return hasBlobBaseFee();
+	case Instruction::SLOTNUM:
+		return hasSlotNum();
 	case Instruction::MCOPY:
 		return hasMcopy();
 	case Instruction::TSTORE:
 	case Instruction::TLOAD:
 		return supportsTransientStorage();
 	default:
 		return true;
 	}
 }
