+    ptls_iovec_t ret = ptls_iovec_init(NULL, 0);
+
+    if (node->type != YOML_TYPE_SCALAR) {
+        return ret;
+    }
+
+    rr_path = node->data.scalar;
+
+    fp = fopen(rr_path, "rb");
+    if (fp == NULL) {
+        fprintf(stderr, "Failed to open file:'%s', error:[%d]:'%s'\n", rr_path, errno, strerror(errno));
+        goto on_config_esni_rr_1;
