+
+    rc = fread(rr, 1, sizeof(rr), fp);
+    if (rc == 0 || !feof(fp)) {
+        fprintf(stderr, "Failed to load ESNI data from file:'%s'\n", rr_path);
+        goto on_config_esni_rr_1;
+    }
+
+    ret = ptls_iovec_init(h2o_mem_alloc(rc), rc);
+    h2o_memcpy(ret.base, rr, rc);
