+    h2o_timer_wheel_slot_t wheel[H2O_TIMERWHEEL_MAX_WHEELS][H2O_TIMERWHEEL_SLOTS_PER_WHEEL], expired;
+    uint64_t last_run; /* the last time h2o_timer_wheel_run was called */
