 	case Token::Sub: // -
 	{
 		defineExpr(_op, 0 - expr(subExpr));
 		break;
 	}
 	case Token::Delete:
 	{
 		if (auto decl = identifierToVariable(subExpr))
 		{
 			m_context.newValue(*decl);
 			m_context.setZeroValue(*decl);
