	unsigned char buf[4096];
	size_t enc = meshopt_encodeMeshlet(buf, sizeof(buf), NULL, 0, reinterpret_cast<const unsigned char*>(data), triangle_count);
	assert(enc > 0);
	assert(enc <= meshopt_encodeMeshletBound(0, triangle_count));

