         self->client = NULL;
         return NULL;
     }
     /* declare the start of the response */
     h2o_start_response(req, &self->super);

     if (errstr == h2o_http1client_error_is_eos) {
         self->client = NULL;
         h2o_send(req, NULL, 0, H2O_SEND_STATE_FINAL);
         return NULL;
     }

     return on_body;
 }
